fn network_content(out: &mut String, scope: &Scope<'_>) {
    out.push_str("\n<h1>Network Settings</h1>\n<div class=\"content-grid\">\n    <section class=\"card\" aria-labelledby=\"discovery-heading\">\n        <h2 id=\"discovery-heading\">OMT discovery</h2>\n        <p>mDNS discovery remains enabled. Configure one optional Discovery Server for routed networks.</p>\n        ");
    if tv::truthy(tv::attr(tv::lookup(scope, "network"), "error")) {
        out.push_str("\n        <p class=\"notice notice-warning\" role=\"status\">");
        tv::render(out, tv::attr(tv::lookup(scope, "network"), "error"));
        out.push_str("</p>\n        ");
    }
    out.push_str("\n        ");
    if tv::truthy(tv::lookup(scope, "configuration_error")) {
        out.push_str("\n        <p class=\"notice notice-warning\" role=\"status\">Saved OMT target is invalid: ");
        tv::render(out, tv::lookup(scope, "configuration_error"));
        out.push_str("</p>\n        ");
    }
    out.push_str("\n        <form method=\"POST\" action=\"/settings/network\">\n            <input type=\"hidden\" name=\"csrf_token\" value=\"");
    tv::render(out, tv::lookup(scope, "csrf_token"));
    out.push_str("\">\n            <div class=\"field\">\n                <label for=\"discovery_server\">Discovery Server</label>\n                <input id=\"discovery_server\" name=\"discovery_server\"\n                       aria-describedby=\"discovery_server_help\"\n                       value=\"");
    tv::render(out, tv::attr(tv::lookup(scope, "network"), "discovery_server_text"));
    out.push_str("\"\n                       placeholder=\"omt://discovery.example:6399\">\n                <p class=\"field-help\" id=\"discovery_server_help\">Enter a host, host:port, or omt://host:port. Port 6399 is used by default.</p>\n            </div>\n            <button type=\"submit\" class=\"button\">Save discovery settings</button>\n        </form>\n    </section>\n    <section class=\"card\" aria-labelledby=\"direct-heading\">\n        <h2 id=\"direct-heading\">Direct target</h2>\n        <p>Connect directly when discovery is unavailable.</p>\n        <form method=\"POST\" action=\"/settings/direct-source\">\n            <input type=\"hidden\" name=\"csrf_token\" value=\"");
    tv::render(out, tv::lookup(scope, "csrf_token"));
    out.push_str("\">\n            <div class=\"field\">\n                <label for=\"direct_address\">OMT target</label>\n                <input id=\"direct_address\" name=\"direct_address\" required\n                       aria-describedby=\"direct_address_help\"\n                       placeholder=\"omt://source.example:6400\"\n                       value=\"");
    tv::render(out, if tv::truthy(tv::lookup(scope, "current_direct_target")) { tv::lookup(scope, "current_direct_target") } else { &LIT_10 });
    out.push_str("\">\n                <p class=\"field-help\" id=\"direct_address_help\">An explicit omt://host:port target is required.</p>\n            </div>\n            <button type=\"submit\" class=\"button\">Save &amp; play direct target</button>\n        </form>\n    </section>\n</div>\n");
}

fn network_title(out: &mut String, scope: &Scope<'_>) {
    out.push_str("Network Settings — ");
    tv::render(out, tv::lookup(scope, "hostname"));
    out.push_str(" OMT Client");
}

static NETWORK_BLOCKS: Blocks = Blocks {
    content: Some(network_content),
    page_class: None,
    title: Some(network_title),
};

fn reboot_confirm_content(out: &mut String, scope: &Scope<'_>) {
    out.push_str("\n<h1>Confirm OS reboot</h1>\n<section class=\"card danger-zone\">\n    <p class=\"eyebrow\">Danger zone</p>\n    <p><strong>The Raspberry Pi will stop playback and go offline.</strong></p>\n    <p>It should return after the operating system and OMT Client service finish starting.</p>\n    <div class=\"button-row\">\n        <form method=\"POST\" action=\"/system/reboot\">\n            <input type=\"hidden\" name=\"csrf_token\" value=\"");
    tv::render(out, tv::lookup(scope, "csrf_token"));
    out.push_str("\">\n            <button type=\"submit\" class=\"button button-danger\">Confirm reboot</button>\n        </form>\n        <a class=\"button button-secondary\" href=\"/system\">Cancel</a>\n    </div>\n</section>\n");
}

